settings.custom_liquid:
{% render 'ns-kz-head' %}<style>
.ks-cmp-sec,.ks-rv-sec{background:radial-gradient(120% 90% at 50% 0,#17304F 0,#0E1A2B 60%)!important}
.ks-cmp-sec__art{display:none}
.ks-cmp-sec .ks__eyebrow,.ks-rv-sec .ks__eyebrow{color:#C8F03C}
.ks-cmp-sec .ks__h,.ks-rv-sec .ks__h{font-family:'Archivo',sans-serif;font-weight:900}
.ks-cmp-sec .ks__p,.ks-rv-sec .ks__p{color:#C9D3E1}
.ks-cmp-sec .ks-cmp__head{background:#13233A!important;border-color:#2A3E5C!important;border-radius:14px 14px 0 0!important}
.ks-cmp-sec thead .ks-cmp__head.is-us{background:#C8F03C!important;color:#0E1A2B!important;border-color:#C8F03C!important;border-radius:14px 14px 0 0!important}
.ks-cmp-sec tbody td{background:#13233A!important;border-color:#2A3E5C!important;color:#C9D3E1}
.ks-cmp-sec tbody td.is-us{background:#1A3326!important;border-left-color:#AFD82A!important;border-right-color:#AFD82A!important;color:#fff}
.ks-cmp-sec tbody tr:last-child td.is-us{border-bottom-color:#AFD82A!important}
.ks-cmp-sec .ks-cmp__ic--yes{color:#C8F03C}
.ks-rv__card{background:#13233A;border-color:#2A3E5C}
.ks-rv__bar span{background:#C8F03C}.ks-rv__btn:hover{border-color:#C8F03C;color:#C8F03C}
.ks-cmp-sec .ks__h,.ks-rv-sec .ks__h{font-size:clamp(30px,3.2vw,46px);word-break:normal;overflow-wrap:normal;hyphens:none}
</style>

{% render 'ns-kz-head' %}<span id="kz-buy" style="position:relative;top:-90px;display:block"></span><style>
[id^="shopify-section-template"][id$="__main"]{background:#EEF1F5}
[id^="shopify-section-template"][id$="__main"] .product__title h1{font-family:'Archivo',sans-serif;font-weight:900;text-transform:uppercase;font-size:clamp(34px,4vw,54px);line-height:.98;letter-spacing:-.01em;color:#111827}
[id^="shopify-section-template"][id$="__main"] variant-selects{display:none!important}
[id^="shopify-section-template"][id$="__main"] .price{display:none}
html.ns-holiday [id^="shopify-section-template"][id$="__main"] .product-form__submit,[id^="shopify-section-template"][id$="__main"] .product-form__submit{background:#C8F03C!important;border-color:#C8F03C!important;color:#0E1A2B!important;box-shadow:0 10px 24px -12px rgba(110,150,0,.7)!important;border-radius:10px;font-weight:800;font-size:16px;letter-spacing:.04em}
html.ns-holiday [id^="shopify-section-template"][id$="__main"] .product-form__submit:hover{background:#AFD82A!important}
.kz-sub{font-family:'Archivo',sans-serif;font-weight:800;font-size:20px;text-transform:uppercase;color:#111827;margin:-6px 0 10px;line-height:1.15}
.kz-tag{font-weight:700;font-size:19px;color:#111827;margin:0 0 6px}
.kz-intro{font-size:14.5px;line-height:1.6;color:#5B6474;margin:0 0 14px}
.kz-tiles{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:4px 0 16px}
.kz-tiles div{background:#fff;border:1px solid #E1E6ED;border-radius:12px;padding:14px;text-align:center}
.kz-tiles svg{color:#5E7E12;margin:0 auto 6px;display:block}
.kz-tiles b{display:block;font-size:12.5px;letter-spacing:.06em;text-transform:uppercase;color:#111827}
.kz-tiles span{font-size:12.5px;color:#5B6474}
.kz-pk-h{font-family:'Archivo',sans-serif;font-weight:900;font-size:17px;text-transform:uppercase;color:#111827;margin:6px 0 10px}
.kzp{display:flex;gap:12px;align-items:center;background:#fff;border:2px solid #DDE3EA;border-radius:14px;padding:14px;margin-bottom:10px;cursor:pointer;position:relative;transition:border-color .15s,background .15s}
.kzp.is-on{border-color:#86B81E;background:#F6FBE8}
.kzp__r{flex:0 0 18px;height:18px;border-radius:50%;border:2px solid #9AA3B2}
.kzp.is-on .kzp__r{border-color:#5E7E12;box-shadow:inset 0 0 0 4px #fff;background:#5E7E12}
.kzp img{width:76px;height:76px;object-fit:cover;border-radius:10px;flex:0 0 76px}
.kzp__n{font-family:'Archivo',sans-serif;font-weight:900;font-size:16px;text-transform:uppercase;color:#111827;display:block}
.kzp__badge{display:inline-block;background:#FFF1D6;color:#9A5B00;font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;border-radius:999px;padding:2px 8px;margin:2px 0 4px}
.kzp ul{list-style:none;margin:2px 0 6px;padding:0;font-size:12.5px;color:#374151;line-height:1.5}
.kzp__p{font-family:'Archivo',sans-serif;font-weight:900;font-size:22px;color:#111827}
.kzp__p s{font-family:Inter,sans-serif;font-weight:500;font-size:14px;color:#8A93A3;margin-left:6px}
.kzp__save{display:inline-block;background:#B3262E;color:#fff;font-size:11px;font-weight:800;border-radius:4px;padding:2px 7px;margin-left:6px;vertical-align:middle}
.kz-trust{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid #DDE3EA;margin-top:8px}
.kz-trust div{display:flex;gap:10px;align-items:flex-start;padding:14px 6px;border-bottom:1px solid #DDE3EA}
.kz-trust div:nth-child(odd){border-right:1px solid #DDE3EA}
.kz-trust svg{color:#5E7E12;flex:0 0 auto}
.kz-trust b{display:block;font-size:12px;letter-spacing:.04em;text-transform:uppercase;color:#111827}
.kz-trust span{font-size:12px;color:#5B6474}
</style>
